class Solution {
  public String lexGreaterPermutation(String s, String target) {
    int n = s.length();
    int[] total = new int[26];
    for (char c : s.toCharArray()) total[c - 'a']++;
    // longest prefix of target that can be spelled with the letters of s
    int[] used = new int[26];
    int feasible = 0;
    while (feasible < n
        && ++used[target.charAt(feasible) - 'a'] <= total[target.charAt(feasible) - 'a'])
      feasible++;
    // a longer shared prefix gives a smaller answer, so try the longest first
    for (int i = Math.min(feasible, n - 1); i >= 0; i--) {
      int[] rest = total.clone();
      for (int t = 0; t < i; t++) rest[target.charAt(t) - 'a']--;
      for (int c = target.charAt(i) - 'a' + 1; c < 26; c++) {
        if (rest[c] == 0) continue;
        rest[c]--;
        StringBuilder sb = new StringBuilder(target.substring(0, i)).append((char) ('a' + c));
        for (int l = 0; l < 26; l++) {
          for (int r = 0; r < rest[l]; r++) sb.append((char) ('a' + l));
        }
        return sb.toString();
      }
    }
    return "";
  }
}
